  <script>
    const tabs = ["Screens", "UI Elements", "Flows", "Text in Screenshot"];
    const filters = ["Profile", "Wallet", "Welcome", "Account Setup", "Home", "Subscription & Paywall", "Login", "Settings", "Checkout", "Collections"];

    const testimonials = [
      {name: "Sebastian Speier", role: "Shop", quote: "ScreenVault is a great resource and it always comes in handy to see what the best practices or standards are for mobile patterns in our current landscape."},
      {name: "Meng To", role: "DesignCode", quote: "ScreenVault is a game-changer for designers looking to step up their understanding of UX and UI design patterns. It's indispensable in the modern designer's toolbox."},
      {name: "Marco Cornacchia", role: "Figma", quote: "ScreenVault is one of my favorite resources for product design and UI inspo. I love having access to real-world examples for specific UI patterns and flows."},
      {name: "Daryl Ginn", role: "Endless", quote: "ScreenVault has quickly become our favourite inspiration resource for designing mobile apps. Their advanced filtering is unmatched."},
      {name: "Rachel How", role: "Independent Designer", quote: "ScreenVault is my go-to reference for app and web design. It saves countless hours and gives immediate insights into top-tier patterns."},
      {name: "Haerin Song", role: "Visa", quote: "I save both research time and gallery space. It's easy to search patterns and copy flows into Figma."}
    ];

    const appBrands = ["Coinbase", "Wise", "Headspace", "Airbnb", "Uber", "Nike", "Pinterest", "ChatGPT", "Shopify", "Loom", "Mailchimp", "Twitch", "Spotify", "Apple TV", "Notion", "Dropbox"];

    let activeTab = "Screens";
    let activeFilter = "Profile";

    const pillsWrap = document.querySelector('.pills');
    const shotGrid = document.getElementById('shotGrid');

    function renderPills() {
      pillsWrap.innerHTML = filters.map((filter) =>
        `<button class="pill ${filter === activeFilter ? 'active' : ''}" data-filter="${filter}">${filter}</button>`
      ).join('');
    }

    function makeItems(tab, filter) {
      return Array.from({length: 8}, (_, i) => ({
        label: `${tab} · ${filter}`,
        id: `${tab.slice(0,2).toUpperCase()}-${filter.slice(0,2).toUpperCase()}-${i+1}`
      }));
    }

    function renderGrid() {
      shotGrid.style.opacity = .2;
      shotGrid.style.transform = 'translateY(4px)';
      window.setTimeout(() => {
        const items = makeItems(activeTab, activeFilter);
        shotGrid.innerHTML = items.map(item => `
          <article class="shot">
            <div class="mini-ui"></div>
            <small>${item.label}</small>
          </article>
        `).join('');
        shotGrid.style.opacity = 1;
        shotGrid.style.transform = 'translateY(0px)';
      }, 120);
    }

    document.querySelectorAll('.tab').forEach(btn => {
      btn.addEventListener('click', () => {
        activeTab = btn.dataset.tab;
        document.querySelectorAll('.tab').forEach(tab => {
          tab.classList.toggle('active', tab === btn);
          tab.setAttribute('aria-selected', tab === btn ? 'true' : 'false');
        });
        renderGrid();
      });
    });

    pillsWrap.addEventListener('click', (event) => {
      const target = event.target.closest('.pill');
      if (!target) return;
      activeFilter = target.dataset.filter;
      renderPills();
      renderGrid();
    });

    const flowContent = {
      "Videos": {
        copy: "Experience flows the way they were meant to be experienced — complete with transitions, micro-interactions, and animations.",
        steps: ["Onboarding introduction video", "Account setup transition", "Paywall decision moment", "Checkout completion animation"]
      },
      "Prototype mode": {
        copy: "Walk through flows step by step using interactive hotspots at your own pace.",
        steps: ["Tap hotspot: Welcome", "Tap hotspot: Profile setup", "Tap hotspot: Subscription", "Tap hotspot: Confirmation"]
      }
    };

    let activeFlowView = "Videos";
    const flowCanvas = document.getElementById('flowCanvas');
    const flowCopy = document.getElementById('flowCopy');

    function renderFlow() {
      const content = flowContent[activeFlowView];
      flowCopy.textContent = content.copy;
      flowCanvas.innerHTML = content.steps.map((step, idx) => `<div class="flow-step ${idx===1 ? 'active' : ''}">${step}</div>`).join('');
    }

    document.querySelectorAll('[data-flow-view]').forEach(btn => {
      btn.addEventListener('click', () => {
        activeFlowView = btn.dataset.flowView;
        document.querySelectorAll('[data-flow-view]').forEach(item => item.classList.toggle('active', item === btn));
        renderFlow();
      });
    });

    function renderTestimonials() {
      const quoteHTML = (item) => `
        <article class="quote">
          <p>“${item.quote}”</p>
          <strong>${item.name}</strong>
          <span>${item.role}</span>
        </article>
      `;
      const rowA = document.getElementById('testiRowA');
      const rowB = document.getElementById('testiRowB');
      const doubled = [...testimonials, ...testimonials];
      rowA.innerHTML = doubled.map(quoteHTML).join('');
      rowB.innerHTML = [...doubled].reverse().map(quoteHTML).join('');
    }

    function renderIcons() {
      const icon = (name) => `<div class="app-icon" title="${name}">${name.split(' ').map(w => w[0]).join('').slice(0,3)}</div>`;
      const doubled = [...appBrands, ...appBrands];
      document.getElementById('iconRowA').innerHTML = doubled.map(icon).join('');
      document.getElementById('iconRowB').innerHTML = [...doubled].reverse().map(icon).join('');
    }

    function animateCounter(el, endValue, duration = 1600, delay = 0) {
      const startTime = performance.now() + delay;
      const startValue = 0;
      const update = (time) => {
        if (time < startTime) {
          requestAnimationFrame(update);
          return;
        }
        const progress = Math.min((time - startTime) / duration, 1);
        const eased = 1 - Math.pow(1 - progress, 3);
        const current = Math.floor(startValue + (endValue - startValue) * eased);
        el.textContent = current.toLocaleString();
        if (progress < 1) requestAnimationFrame(update);
      };
      requestAnimationFrame(update);
    }

    function initStatsObserver() {
      const statsSection = document.getElementById('stats');
      const counters = Array.from(document.querySelectorAll('[data-counter]'));
      let played = false;

      const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting && !played) {
            played = true;
            counters.forEach((counter, i) => animateCounter(counter, Number(counter.dataset.counter), 1500, i * 150));
            observer.disconnect();
          }
        });
      }, { threshold: 0.35 });

      observer.observe(statsSection);
    }

    renderPills();
    renderGrid();
    renderFlow();
    renderTestimonials();
    renderIcons();
    initStatsObserver();
  </script>
